class Solution:
    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:
        m, n = len(grid), len(grid[0]); r = c = 0; seen = set()
        moves = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
        while (r, c) not in seen:
            seen.add((r, c)); dr, dc = moves[grid[r][c]]
            nr, nc = r + dr, c + dc
            if not (0 <= nr < m and 0 <= nc < n) or (nr, nc) in seen: break
            r, c = nr, nc
        return [r, c]

